package com.jgeted.sagadyssey.core.structure;

import com.jgeted.sagadyssey.core.MinecraftApi;
import com.jgeted.sagadyssey.Sagadyssey;
import com.jgeted.sagadyssey.npc.brain.fieldwork.*;
import com.jgeted.sagadyssey.social.household.*;
import com.jgeted.sagadyssey.social.politics.*;
import com.jgeted.sagadyssey.social.needs.*;
import com.jgeted.sagadyssey.worldsim.lod.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.world.Container;
import net.minecraft.world.item.Items;
import java.util.*;
/** No test food movement, matured blocks, AI suppression or injected hunger: observe the actual autonomous chain. */
public final class SocietyAutonomousGrowthGameTests {
 private static int count(Container c){int n=0;if(c!=null)for(int i=0;i<c.getContainerSize();i++)if(c.getItem(i).is(Items.CARROT))n+=c.getItem(i).getCount();return n;}
 private static int actual(GameTestHelper h,List<NaturalVillageBuilding> villages){int n=0;for(var b:villages){for(var p:NaturalVillageLayout.stores(b))n+=count((Container)h.getLevel().getBlockEntity(NaturalVillageLayout.at(b,p)));for(int i=0;i<3;i++){var a=NaturalVillageR1GameTests.actor(h.getLevel(),b,i);if(a!=null)n+=count(a.getPersonalInventory())+count(a.getTransportInventory());}}return n;}
 private static int delta(GameTestHelper h,List<NaturalVillageBuilding> villages){int n=0;for(var b:villages)for(int i=0;i<3;i++)n+=FieldworkData.get(h.getLevel().getServer()).receiptsFor(NaturalVillageLifeData.body(b,i)).stream().flatMap(r->r.inventoryDeltas().stream()).filter(d->d.fingerprint().equals("minecraft:carrot#0")).mapToInt(FieldworkActionReceipt.ItemDelta::quantity).sum();return n;}
 private static long[] remote(GameTestHelper h,List<NaturalVillageBuilding> villages){long[] result={0,0,0};var d=NaturalVillageEconomyData.get(h.getLevel().getServer());for(var b:villages){var row=d.row(b.buildingKey());if(!row.contains("Clock"))continue;var clock=RemoteCropClock.load(row.getCompoundOrEmpty("Clock"));result[0]+=clock.produced()-clock.planted();result[1]+=row.getLongOr("Meals", 0L);for(var e:MinecraftApi.listOfType(row, "Stores",Tag.TAG_COMPOUND))result[2]+=count(NaturalVillageEconomyData.inventory(MinecraftApi.listOfType(((CompoundTag)e), "Items",Tag.TAG_COMPOUND),h.getLevel().registryAccess()));}return result;}
 public static void run(GameTestHelper h){var l=h.getLevel();var s=l.getServer();var farm=NaturalVillageR1GameTests.fixture(h,0,NaturalVillageLayout.FARM_V2);var wood=NaturalVillageR1GameTests.fixture(h,96,NaturalVillageLayout.WOOD_V2);var villages=List.of(farm,wood);var meals=new HashSet<String>();int[] stage={0},last={-1},frozenBags={0};long[] builtAt={0},target={0};
  h.onEachTick(()->{if(last[0]==s.getTickCount())return;last[0]=s.getTickCount();for(var b:villages)NaturalVillageR1GameTests.observe(l,b,meals);var polity=NaturalPolityData.get(s);var row=polity.site(farm.settlementId());if(row==null)return;var project=row.getCompoundOrEmpty("Project");int construction=project.getStringOr("Stage", "").equals("DONE")?4:0;
   if(s.getTickCount()%12000==0)Sagadyssey.LOGGER.info("R3_AUTONOMOUS_PROGRESS stage={} tick={} hostPop={} surplus={} project={} migration={} trade={}",stage[0],h.getTick(),NaturalPolityData.population(s,farm).size(),NaturalPolityData.availableFood(s,farm),project,NaturalHouseholdMigrationData.get(s).moves().stream().map(t->t.getStringOr("State", "")+":"+t.getStringOr("Reason", "")).toList(),SettlementExchangeData.get(s).deals().stream().map(t->t.getStringOr("State", "")).toList());
   if(stage[0]==0){if(h.getTick()>220&&s.getTickCount()%200==0)h.assertTrue(32+delta(h,villages)==actual(h,villages)+meals.size()+construction,"autonomous near food balance including real construction rations");if(!project.getStringOr("Stage", "").equals("DONE"))return;
    h.assertTrue(NaturalHouseholdMigrationData.get(s).moves().stream().anyMatch(t->t.getStringOr("State", "").equals("DONE"))&&SettlementExchangeData.get(s).deals().stream().anyMatch(t->t.getStringOr("State", "").equals("DONE"))&&NaturalPolityData.population(s,farm).size()==6,"actual natural production financed trade, depleted-forest opportunity caused original migration, and material surplus built a bed");builtAt[0]=l.getGameTime();stage[0]=1;
   }
   if(stage[0]==1){if(l.getGameTime()-builtAt[0]<12000)return;var arrival=polity.inventory(s,farm,4);h.assertTrue(count(arrival)>0||meals.size()>6,"actual admitted household receives and consumes consented food rather than fictitious stocks");if(SupplyFlowData.get(s).routes().stream().anyMatch(r->!r.closed()&&(r.principal().id().equals(NaturalVillageLifeData.home(farm))||r.principal().id().equals(NaturalVillageLifeData.home(wood)))))return;
    for(var b:villages)for(int i=0;i<3;i++){var a=NaturalVillageR1GameTests.actor(l,b,i);frozenBags[0]+=count(a.getPersonalInventory())+count(a.getTransportInventory());}for(var b:villages)NaturalVillageR1GameTests.visiting(l,b,false);stage[0]=2;
   }
   if(stage[0]==2){var data=NaturalVillageEconomyData.get(s);for(var b:villages){if(!data.row(b.buildingKey()).getStringOr("Phase", "").equals("REMOTE"))return;for(int i=0;i<3;i++)if(NaturalVillageR1GameTests.actor(l,b,i)!=null)return;}target[0]=l.getGameTime()+60000;s.getWorldData().overworldData().setGameTime(target[0]);l.setDayTime(l.getDayTime()+60000);stage[0]=3;}
   if(stage[0]==3){var data=NaturalVillageEconomyData.get(s);if(data.backlog(l.getGameTime())>0)return;var r=remote(h,villages);h.assertTrue(32+delta(h,villages)+r[0]==r[2]+frozenBags[0]+meals.size()+r[1]+4,"remote original and incoming families share one exact food account");h.assertTrue(MinecraftApi.listOfType(data.row(farm.buildingKey()), "Receipts",Tag.TAG_COMPOUND).stream().anyMatch(e->((CompoundTag)e).getStringOr("Kind", "").equals("ARRIVAL_SUPPLY_DELIVERED")),"original incoming carrier and recorded consent support a real timed remote food transfer");for(var b:villages)NaturalVillageR1GameTests.visiting(l,b,true);stage[0]=4;}
   if(stage[0]==4){var data=NaturalVillageEconomyData.get(s);if(villages.stream().anyMatch(b->!data.row(b.buildingKey()).getStringOr("Phase", "").equals("NEAR")))return;for(var b:villages)for(int i=0;i<3;i++)if(NaturalVillageR1GameTests.actor(l,b,i)==null)return;var r=remote(h,villages);h.assertTrue(32+delta(h,villages)+r[0]==actual(h,villages)+meals.size()+r[1]+4,"original six bodies and both families return with exact stock, production, seed and meal accounting");h.assertTrue(NaturalPolityData.population(s,farm).size()==6&&NaturalPolityData.population(s,wood).isEmpty(),"no departed ghosts or duplicated arriving people");Sagadyssey.LOGGER.info("R3_AUTONOMOUS_ACCEPT ticks={} naturalNet={} remoteNet={} nearMeals={} remoteMeals={} physicalFood={} actualBed=1 originalPeople=6 testFoodTransfers=0 importedFamilyRemoteSupply=true",h.getTick(),delta(h,villages),r[0],meals.size(),r[1],actual(h,villages));NaturalVillageR3GameTests.checkpoint(h,villages);h.succeed();stage[0]=5;}
  });
 }
}
